#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
layout(color) uniform half4 amzp_color1;
layout(color) uniform half4 amzp_color2;
uniform float amzp_angle;
uniform float2 amzp_offset;
uniform float amzp_scale;
uniform float amzp_alpha;
uniform float amzp_gradType;
uniform float amzp_bright;
uniform float amzp_blendMode;
uniform float amzp_alphab;
        const float3 luminanceWeighting = float3(0.2126, 0.7152, 0.0722);
        float3 hsv2rgb(float3 c)
        {
            float4 K = float4(1.0, 2.0 / 3.0, 1.0 / 3.0, 3.0);
            float3 p = abs(fract(c.xxx + K.xyz) * 6.0 - K.www);
            return c.z * mix(K.xxx, clamp(p - K.xxx, 0.0, 1.0), c.y);
        }
        float3 rgb2hsv(float3 c)
        {
            float4 K = float4(0.0, -1.0 / 3.0, 2.0 / 3.0, -1.0);
            float4 p = mix(float4(c.bg, K.wz), float4(c.gb, K.xy), step(c.b, c.g));
            float4 q = mix(float4(p.xyw, c.r), float4(c.r, p.yzx), step(p.x, c.r));
            float d = q.x - min(q.w, q.y);
            float e = 1.0e-10;
            return float3(abs(q.z + (q.w - q.y) / (6.0 * d + e)), d / (q.x + e), q.x);
        }
             float3x3 rgb2yuv = float3x3(
                 0.299, 0.587, 0.114,
                -0.14713, -0.28886, 0.436,
                 0.615, -0.51499, -0.10001
            );
             float3x3 yuv2rgb = float3x3(
                1.0, 0.0, 1.13983,
                1.0, -0.39465, -0.58060,
                1.0, 2.03211, 0.0
            );
        void amzRender() {
            float4 texColor = amzTexture(0,amzScreenNorm());
            float a = amzp_angle * 0.0174533;
            float2 st = amzLayerNorm();
            st -= 0.5;
            st -= (amzp_offset*float2(1,-1)) / 500.;
            st /= amzp_scale;
            st *= float2x2(
                sin(a), -cos(a),
                cos(a), sin(a)
            );
            st += 0.5;
            float t;
            if( int(amzp_gradType) == 0 ) {
                t = st.x;
            } else if ( int(amzp_gradType) == 1 ) {
                t = length( st - 0.5 ) * 2.0;
            } else if ( int(amzp_gradType) == 2 ) {
                float2 xy = st - 0.5;
                float2 zw = float2(0,1.0);
                float a = atan(xy.x, xy.y);
                float b = atan(zw.x, zw.y);
                t = mod(((a-b)+6.28),6.28)/6.28;
            } else {
                t = st.x;
            }
            t = clamp(t,0.0,1.0);
            float4 color = mix(amzp_color1, amzp_color2, t);
            float4 result;
            if( int(amzp_blendMode)==1 ) {
                result = float4((texColor.rgb/texColor.a)*color.rgb,1.0) * texColor.a;
            } else if( int(amzp_blendMode)==2 ) {
                result = float4( 1.-((1.-(texColor.rgb/texColor.a))*(1.-color.rgb)),1.0) * texColor.a;
            } else {
                result = float4(color.rgb,1.0)*texColor.a;
            }
            float4 fragColor = mix(texColor,result,amzp_alpha*color.a);
        float4 texColorX = float4(0.0,0.0,0.0,1.0) * texColor.a;
     float4 factor = mix(texColorX,fragColor,1.0);
        float4 resultfinal;
        if( int(amzp_blendMode)==0 ) {
            resultfinal = (factor * amzp_bright) * texColor.a;
        } else if( int(amzp_blendMode)==1 ) {
            factor *= amzp_bright;
            float4 c = factor + float4(1.)*(1.-factor.a);
            resultfinal = float4((texColor.rgb/texColor.a)*c.rgb,1.0) * texColor.a;
        } else if( int(amzp_blendMode)==2 ) {
            factor *= amzp_bright;
            resultfinal = float4( 1.-((1.-(texColor.rgb/texColor.a))*(1.-factor.rgb)),1.0) * texColor.a;
        } else if(int(amzp_blendMode)==3 ) {
            factor *= amzp_bright;
            float3 t = smoothstep(0.5,0.5,texColor.rgb);
            float3 result =
                    t * (1. - (1.-2.*(texColor.rgb-0.5)) * (1.-factor.rgb)) +
                    (1.-t) * ((2.*texColor.rgb) * factor.rgb);
            resultfinal = float4(result, texColor.a) * texColor.a;
        } else if(int(amzp_blendMode)==4 ) {
            float3 colorBlend = float3( (texColor.rgb * rgb2yuv).r, (factor.rgb * rgb2yuv).gb) * yuv2rgb;
            resultfinal = float4(colorBlend,texColor.a) * texColor.a;
        } else if(int(amzp_blendMode)==5 ) {
            factor *=amzp_bright;
            resultfinal = max(factor,texColor) * texColor.a;
        } else if(int(amzp_blendMode)==6 ) {
            factor *=amzp_bright;
            resultfinal = texColor / (1.0-factor) * texColor.a;
        } else if(int(amzp_blendMode)==7 ) {
            factor *=amzp_bright;
            resultfinal = (1. - (1.-texColor) / factor) * texColor.a;
        } else if(int(amzp_blendMode)==8 ) {
            factor *=amzp_bright;
            resultfinal = (texColor + factor) * texColor.a;
        } else if(int(amzp_blendMode)==9 ) {
            factor *=amzp_bright;
            resultfinal = (texColor + factor - 1.0) * texColor.a;
        } else if(int(amzp_blendMode)==10 ) {
            float3 t = smoothstep(0.5,0.5,factor.rgb);
            float3 linearLight =
                    t * (texColor.rgb + 2.*(factor.rgb-0.5)) +
                    (1.-t) * (texColor.rgb + 2.*factor.rgb - 1.);
            resultfinal = float4(linearLight,texColor.a) * texColor.a;
        } else if(int(amzp_blendMode)==11 ) {
            factor *=amzp_bright;
            resultfinal = min(factor,texColor) * texColor.a;
        } else if(int(amzp_blendMode)==12 ) {
            factor *=amzp_bright;
            float3 darkenColor = length(luminanceWeighting * factor.rgb) > length(luminanceWeighting * texColor.rgb) ? texColor.rgb : factor.rgb;
            resultfinal = float4(darkenColor,texColor.a) * texColor.a;
        } else if(int(amzp_blendMode)==13 ) {
            factor *=amzp_bright;
            float3 lightenColor = length(luminanceWeighting * factor.rgb) > length(luminanceWeighting * texColor.rgb) ? factor.rgb : texColor.rgb;
            resultfinal = float4(lightenColor,texColor.a) * texColor.a;
        } else if(int(amzp_blendMode)==14 ) {
            factor *=amzp_bright;
            float3 t = smoothstep(0.5,0.5,factor.rgb);
            float3 softLight =
                    t * (1. - (1.-texColor.rgb) * (1.-(factor.rgb-0.5))) +
                    (1.-t) * (texColor.rgb * (factor.rgb+0.5));
            resultfinal = float4(softLight,texColor.a) * texColor.a;
        } else if(int(amzp_blendMode)==15 ) {
            factor *=amzp_bright;
            float3 t = smoothstep(0.5,0.5,texColor.rgb);
            float3 softOver =
                    t * (1. - (1.-texColor.rgb) * (1.-(factor.rgb-0.5))) +
                    (1.-t) * (texColor.rgb * (factor.rgb+0.5));
            resultfinal = float4(softOver,texColor.a) * texColor.a;
        } else if(int(amzp_blendMode)==16 ) {
            factor *=amzp_bright;
            float3 t = smoothstep(0.5,0.5,factor.rgb);
            float3 hardLight =
                    t * (1. - (1.-texColor.rgb) * (1.-2.*(factor.rgb-0.5))) +
                    (1.-t) * (texColor.rgb * (2.*factor.rgb));
            resultfinal = float4(hardLight,texColor.a) * texColor.a;
        } else if(int(amzp_blendMode)==17 ) {
            factor *=amzp_bright;
            float3 hueB = hsv2rgb(float3(rgb2hsv(factor.rgb).r, rgb2hsv(texColor.rgb).gb));
            resultfinal = float4(hueB,texColor.a) * texColor.a;
        } else if(int(amzp_blendMode)==18 ) {
            factor *=amzp_bright;
            resultfinal = float4(abs(texColor.rgb*texColor.a - factor.rgb),texColor.a);
        } else if(int(amzp_blendMode)==19 ) {
            factor *=amzp_bright;
            float3 lumin = float3( (factor.rgb * rgb2yuv).r, (texColor.rgb * rgb2yuv).gb) * yuv2rgb;
            resultfinal = float4(lumin,texColor.a) * texColor.a;
        } else if(int(amzp_blendMode)==20 ) {
            factor *=amzp_bright;
            float3 bot_hsv = rgb2hsv(texColor.rgb);
            float3 satBlend = hsv2rgb(float3(bot_hsv.r, rgb2hsv(factor.rgb).g, bot_hsv.b));
            resultfinal = float4(satBlend,texColor.a) * texColor.a;
        } else if(int(amzp_blendMode)==21 ) {
            factor *=amzp_bright;
            float3 t = smoothstep(0.5,0.5,factor.rgb);
            float3 vividLight =
                    t * (1. - (1.-texColor.rgb) * (2.*(factor.rgb-0.5))) +
                    (1.-t) * (texColor.rgb * (1.-2.*factor.rgb));
            resultfinal = float4(vividLight,texColor.a) * texColor.a;
        } else if(int(amzp_blendMode)==22 ) {
            factor *=amzp_bright;
            float3 t = smoothstep(0.5,0.5,factor.rgb);
            float3 pinLight =
                    t * (max(texColor.rgb,2.*(factor.rgb-0.5))) +
                    (1.-t) * (min(texColor.rgb,2.*factor.rgb));
            resultfinal = float4(pinLight,texColor.a) * texColor.a;
        } else if(int(amzp_blendMode)==23 ) {
            factor *=amzp_bright;
            resultfinal = (texColor / factor) * texColor.a;
        } else if(int(amzp_blendMode)==24 ) {
            factor *=amzp_bright;
            resultfinal = (texColor - factor) * texColor.a;
        }
     amzOutput = mix(fragColor, resultfinal, amzp_alphab) * texColor.a;
        }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
